<?php
$db=\Drupal::database();$h=\Drupal::service('roma_booking.hotel');$l=\Drupal::service('roma_finance.ledger');$checks=[];
$check=function(bool $ok,string $label)use(&$checks){if(!$ok)throw new \RuntimeException($label);$checks[]=$label;echo 'OK '.$label."\n";};
$reject=function(callable $fn,string $label)use($check){try{$fn();}catch(\DomainException){$check(TRUE,$label);return;}$check(FALSE,$label);};
$key=fn()=>bin2hex(random_bytes(24));$tx=$db->startTransaction();
try{
 $check($l::cents('50,25')===5025&&$l::cents('0.01')===1,'Importes exactos en céntimos sin redondeo binario');
 foreach(['0','-1','1.001','1e3','999999999999','1,000.00'] as $value)$reject(fn()=>$l::cents($value),'Importe inválido rechazado: '.$value);
 $a=(new \DateTimeImmutable($h->today()))->modify('+140 days')->format('Y-m-d');$d=(new \DateTimeImmutable($a))->modify('+2 days')->format('Y-m-d');
 $room=$h->saveItem('room',0,['code'=>'QA-FIN-'.bin2hex(random_bytes(3)),'type_id'=>1,'active'=>1]);
 $r=$h->request(['room_id'=>$room,'arrival'=>$a,'departure'=>$d,'guests'=>1,'customer_name'=>'Cliente ficticio cuenta','email'=>'finance@example.invalid']);$id=$r['id'];$base=$r['estimated_price'];
 $account=$l->account($id);$check(!$account['open']&&!$account['entries'],'Consultar no abre la cuenta ni crea cargos');
 $reject(fn()=>$l->record($id,'charge',500,'Cargo de ensayo','',$key(),1),'No se escribe en una cuenta sin abrir');
 $l->open($id,1);$account=$l->open($id,1);$check(count($account['entries'])===1&&$account['charges']===$base,'Apertura idempotente toma el estimado original');
 $reject(fn()=>$l->record($id,'payment',1000,'Adelanto ficticio','cash_demo',$key(),1),'Reserva pendiente no admite adelanto simulado');
 $h->transition($id,'confirmed',1);
 $k=$key();$p=$l->record($id,'payment',3025,'Primer adelanto ficticio','cash_demo',$k,1);
 $check($l->account($id)['balance']===$base-3025,'Adelanto reduce saldo con precisión');
 $check((int)$db->select('roma_notification','n')->condition('reservation_id',$id)->condition('kind','finance')->countQuery()->execute()->fetchField()===2,'Cargo inicial y adelanto encolan avisos financieros atómicos');
 $same=$l->record($id,'payment',3025,'Primer adelanto ficticio','cash_demo',$k,1);$check($same['id']===$p['id']&&count($l->entries($id))===2,'Reenvío del mismo movimiento no duplica el pago');
 $check((int)$db->select('roma_notification','n')->condition('reservation_id',$id)->condition('kind','finance')->countQuery()->execute()->fetchField()===2,'Reenviar un pago no duplica su aviso n8n');
 $reject(fn()=>$l->record($id,'payment',3026,'Primer adelanto ficticio','cash_demo',$k,1),'Identificador reutilizado con otro importe es rechazado');
 $reject(fn()=>$l->record($id,'payment',1,'Intento de medio real','real_bank',$key(),1),'No se admiten medios de cobro real');
 $charge=$l->record($id,'charge',2000,'Servicio adicional ficticio','',$key(),1);
 $l->record($id,'discount',1000,'Descuento comercial ficticio','',$key(),1);
 $check($l->account($id)['charges']===$base+1000,'Cargos y descuentos se reflejan por separado');
 $rest=$l->account($id)['balance'];$payment=$l->record($id,'payment',$rest,'Cancelación simulada del saldo','transfer_demo',$key(),1);
 $check($l->account($id)['balance']===0,'Pago del saldo deja cuenta saldada');
 $reject(fn()=>$l->record($id,'payment',1,'Pago superior al saldo','cash_demo',$key(),1),'No se permiten pagos superiores al saldo');
 $refund=$l->record($id,'refund',2000,'Devolución parcial ficticia','transfer_demo',$key(),1);$check($l->account($id)['balance']===2000,'Devolución reduce pagado y vuelve a reflejar saldo');
 $discount=$l->record($id,'discount',3000,'Ajuste posterior de tarifa','',$key(),1);$check($l->account($id)['balance']===-1000,'Descuento posterior puede mostrar saldo a favor del huésped');
 $l->record($id,'refund',1000,'Devolución del saldo a favor','cash_demo',$key(),1);$check($l->account($id)['balance']===0,'Devolución del saldo a favor vuelve a saldar');
 $paid=$l->account($id)['collected'];$reject(fn()=>$l->record($id,'refund',$paid+1,'Devolución excesiva ficticia','cash_demo',$key(),1),'Devolución no supera el pagado neto');
 $reject(fn()=>$l->record($id,'discount',$base+10000,'Descuento excesivo ficticio','',$key(),1),'Descuento no deja cargos netos negativos');
 $reverseKey=$key();$reverse=$l->reverse((int)$p['id'],'Corrección del adelanto ficticio',$reverseKey,1);
 $check($l->account($id)['balance']===3025,'Anulación agrega efecto inverso del adelanto');
 $check($l->entry((int)$p['id'])['kind']==='payment'&&$reverse['reverses_id']===$p['id'],'El registro original se conserva con su contrapartida');
 $check($l->reverse((int)$p['id'],'Corrección del adelanto ficticio',$reverseKey,1)['id']===$reverse['id'],'Repetir anulación no duplica contrapartidas');
 $reject(fn()=>$l->reverse((int)$p['id'],'Nueva anulación repetida',$key(),1),'No se anula dos veces el mismo original');
 $reject(fn()=>$l->reverse((int)$reverse['id'],'Reversión de una reversión',$key(),1),'No se encadenan anulaciones de contrapartidas');
 $reject(fn()=>$l->reverse((int)$payment['id'],'Anulación con devoluciones posteriores',$key(),1),'Anulación no deja pagado neto negativo');
 $count=count($l->entries($id));$reject(fn()=>$l->record($id,'charge',100,'x','',$key(),1),'Motivo demasiado corto es rechazado');$check(count($l->entries($id))===$count,'Una validación fallida no guarda movimientos parciales');
 $before=$l->account($id)['charges'];$db->update('roma_rate')->fields(['amount'=>9900])->condition('type_id',1)->execute();$check($l->account($id)['charges']===$before,'Modificar tarifa no cambia el cargo inicial guardado');
 $h->transition($id,'cancelled',1);$reject(fn()=>$l->record($id,'payment',1,'Pago de reserva cancelada','cash_demo',$key(),1),'Reserva cancelada no admite nuevos pagos');
 $l->record($id,'refund',100,'Devolución tras cancelar','cash_demo',$key(),1);$check($l->account($id)['collected']===$paid-3025-100,'Una cancelación permite registrar devoluciones explícitas');
 $report=$l->overview($h->today(),$h->today());$check($report['count']>=count($l->entries($id)),'Reporte incluye movimientos del día de Perú');
 $reject(fn()=>$l->overview('2026-02-30',$h->today()),'Reporte rechaza fecha inexistente');
 $reject(fn()=>$l->overview('2027-01-02','2027-01-01'),'Reporte rechaza periodo invertido');
 $check(array_unique(array_column($l->entries($id),'mode'))===['demo'],'Todos los movimientos se guardan en modo demo');
 echo 'Total: '.count($checks)." comprobaciones. Datos revertidos.\n";
}finally{$tx->rollBack();}
